import {STAT_NAMES} from '../content/living-world.js?v=0.8.0';
import {ENEMIES,ZONES,ITEM_TEMPLATES} from '../content/region.js?v=0.3.1';
import {SETS} from '../content/progression.js?v=0.3.1';
import {CLASSES} from '../content/classes.js?v=0.3.1';
import {SET_EFFECTS,activeSets,trophySet} from '../core/growth.js?v=0.7.0';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderGrowthPanel(name,h,s){
if(name==='bestiary')return{title:'Бестіарій · трофеї полювання',html:`<p class="notice">Записи відкриваються після першої перемоги. За ворога, який дає EXP: 1 трофей, за боса — 5. Обмін 20 трофеїв одного виду на обрану частину комплекту біля привалу, кузні або сховища. Трофеї не займають торбу. Виготовлені речі особисті.</p>${h.huntTarget?'<button class="btn secondary" data-hunt-track="stop">Завершити полювання · повернути стрілку квесту</button>':''}<div class="card-grid">${Object.entries(ENEMIES).sort(([a],[b])=>Number(!!h.bestiary?.[b])-Number(!!h.bestiary?.[a])).map(([id,e])=>{const b=h.bestiary?.[id],entry=trophySet(h,id),zones=Object.values(ZONES).filter(z=>z.enemies.some(x=>x.type===id));return `<article class="card"><h3>${b?esc(e.name):'Невідома істота'} · ${e.level} рів.</h3>${b?`<button class="btn" data-hunt-track="${id}">Відстежувати істоту</button><p>${esc(e.role)}<br>Перемог: ${b.kills} · трофеїв: ${b.trophies}/20</p><p>Здобич: ${esc(ITEM_TEMPLATES[e.loot]?.name)}; можливі зілля, руна й класове спорядження.</p><p>Місця: ${zones.map(z=>esc(z.name)).join(', ')}</p>${entry?`<p>Гарантований комплект: ${esc(entry[1].name)} · рів. ${entry[1].level}</p>${entry[1].pieces.map(t=>`<button class="btn secondary" data-trophy-enemy="${id}" data-template="${t}" ${b.trophies<20||h.level<entry[1].level?'disabled':''}>${esc(ITEM_TEMPLATES[t].name)} · 20 трофеїв</button><button class="btn secondary" data-hunt-track="${id}" data-template="${t}">Відстежувати цю нагороду</button>`).join('')}`:'<p>Цей ворог ще не дає комплектів. Трофеї зберігаються як здобуток.</p>'}`:'<p>Подолайте цю істоту, щоб відкрити запис.</p>'}</article>`}).join('')}</div>`};
if(name==='sets'){const counts=activeSets(h);return{title:'Класові комплекти',html:`<p class="notice">Дві частини одного комплекту активують бойовий ефект. Внутрішнє відновлення — 8 с, зберігається при заміні спорядження. Третя частина додає числові бонуси; можна залишити класову реліквію та носити дві частини комплекту.</p><p class="notice">${SET_EFFECTS[h.classId]}</p><button class="btn" data-open="bestiary">Де добути спорядження</button><div class="card-grid">${Object.entries(SETS).filter(([,t])=>t.classId===h.classId).map(([id,t])=>`<article class="card"><h3>${esc(t.name)} · ${counts[id]||0}/3</h3><p>Рівень ${t.level}</p>${Object.entries(t.bonuses).map(([n,mods])=>`<p>${n} частини: ${Object.entries(mods).map(([k,v])=>(STAT_NAMES[k]||k)+' +'+v).join(', ')}</p>`).join('')}<p>${t.pieces.map(p=>esc(ITEM_TEMPLATES[p].name)).join('<br>')}</p></article>`).join('')}</div>`};}
if(name==='builds')return{title:'Два набори білда',html:`<p class="notice">Збереження та перемикання — біля привалу, кузні або сховища поза боєм. Речі мають бути в торбі. Ранги навичок, куплені покращення, характеристики та відновлення спільні для обох наборів. Зміна напряму навички коштує 3 відлуння (перше відкриття — 2); відсутній у наборі напрям не скасовує поточний.</p><div class="reward-grid">${[0,1].map(slot=>{const b=h.builds?.[slot],cost=b?Object.entries(b.augments).reduce((n,[id,c])=>n+(h.skillAugments[id]===c?0:h.skillAugments[id]?3:2),0):0;return `<article class="card"><h3>Набір ${slot+1}</h3>${b?`<p>${Object.values(b.equipment).map(id=>{const it=[...h.inventory,...(h.storage||[])].find(x=>x.id===id);return id?esc(ITEM_TEMPLATES[it?.template]?.name||'Предмет відсутній'):'Порожня комірка';}).join('<br>')}</p><p>${b.skillbar.map(id=>esc(CLASSES[h.classId].skills.find(x=>x.id===id)?.name)).join(' · ')}</p><button class="btn" data-build-apply="${slot}">Застосувати · ${cost} відлунь</button>`:'<p>Ще не збережений.</p>'}<details><summary>${b?'Перезаписати поточним білдом':'Зберегти поточний білд'}</summary><button class="btn secondary" data-build-save="${slot}">Підтвердити збереження</button></details></article>`}).join('')}</div>`};
return null;}
